        // verificar si la gema forma parte de una línea consecutiva de tres o más gemas iguales
        // (esta implementación es un ejemplo básico y se puede mejorar)
        int count = 0;
        for (int i = -1; i <= 1; i++)
        {
            for (int j = -1; j <= 1; j++)
