            isMatched = true;
        }
        else
        {
            isMatched = false;
        }
    }

    Gem GetGem(int newRow, int newColumn)
    {
        // buscar la gema en la nueva posición
        foreach (Gem gem in GameObject.FindObjectsOfType<Gem>())
        {
            if (gem.row == newRow && gem.column == newColumn)
            {
                return gem;
            }
        }
        return null;
    }
}
